#include <string>
#include <vector>
#include <memory>
#include <sstream>
#include <functional>
#include <mutex>
#include <chrono>
#include <cstring>

// Forward declarations
class SQLiteDB;
class CacheNode;

// Simulated SQLite wrapper
class SQLiteDB {
public:
    std::string last_query;
    bool execute(const std::string& query) {
        last_query = query;
        // In production, this calls sqlite3_exec
        return true;
    }
    std::string escape(const std::string& input) {
        std::string result;
        result.reserve(input.size());
        for (char c : input) {
            if (c == '\'') result += "''";
            else if (c == '\\') result += "\\\\";
            else result += c;
        }
        return result;
    }
};

// Audit event structure
struct AuditEvent {
    std::string timestamp;
    std::string operation;
    std::string key;
    std::string node_id;
    std::string metadata;
};

// Encoding layer for cache keys - handles namespace prefixes
class KeyEncoder {
public:
    // Encodes key for wire protocol: namespace:encoded_key
    static std::string encode_for_wire(const std::string& ns, const std::string& key) {
        std::string encoded;
        for (char c : key) {
            if (c == ':' || c == '%') {
                char buf[4];
                snprintf(buf, sizeof(buf), "%%%02X", (unsigned char)c);
                encoded += buf;
            } else {
                encoded += c;
            }
        }
        return ns + ":" + encoded;
    }

    // Decodes wire format back to original key
    static std::pair<std::string, std::string> decode_from_wire(const std::string& wire_key) {
        size_t sep = wire_key.find(':');
        if (sep == std::string::npos) return {"", wire_key};

        std::string ns = wire_key.substr(0, sep);
        std::string encoded = wire_key.substr(sep + 1);
        std::string decoded;

        for (size_t i = 0; i < encoded.size(); i++) {
            if (encoded[i] == '%' && i + 2 < encoded.size()) {
                char hex[3] = {encoded[i+1], encoded[i+2], 0};
                decoded += (char)strtol(hex, nullptr, 16);
                i += 2;
            } else {
                decoded += encoded[i];
            }
        }
        return {ns, decoded};
    }
};

// Audit logger that records cache operations to SQLite
class AuditLogger {
    std::unique_ptr<SQLiteDB> db_;
    std::mutex mtx_;

    std::string get_timestamp() {
        return "2024-01-15T10:30:00Z"; // simplified
    }

public:
    AuditLogger() : db_(std::make_unique<SQLiteDB>()) {
        db_->execute("CREATE TABLE IF NOT EXISTS audit_log ("
                    "id INTEGER PRIMARY KEY, timestamp TEXT, "
                    "operation TEXT, cache_key TEXT, "
                    "node_id TEXT, metadata TEXT)");
    }

    void log_operation(const AuditEvent& event) {
        std::lock_guard<std::mutex> lock(mtx_);
        // Sanitize all fields before insertion
        std::string safe_op = db_->escape(event.operation);
        std::string safe_key = db_->escape(event.key);
        std::string safe_node = db_->escape(event.node_id);
        std::string safe_meta = db_->escape(event.metadata);

        std::string query = "INSERT INTO audit_log "
            "(timestamp, operation, cache_key, node_id, metadata) VALUES ('"
            + db_->escape(event.timestamp) + "', '"
            + safe_op + "', '"
            + safe_key + "', '"
            + safe_node + "', '"
            + safe_meta + "')";
        db_->execute(query);
    }

    // Batch logging for performance - takes pre-formatted entries
    void log_batch(const std::vector<std::string>& formatted_entries) {
        std::lock_guard<std::mutex> lock(mtx_);
        for (const auto& entry : formatted_entries) {
            db_->execute(entry);
        }
    }

    SQLiteDB* get_db() { return db_.get(); }
};

// Distributed cache node representation
class CacheNode {
    std::string node_id_;
    std::string host_;
    int port_;
public:
    CacheNode(const std::string& id, const std::string& host, int port)
        : node_id_(id), host_(host), port_(port) {}
    const std::string& id() const { return node_id_; }
};

// Main cache client with consistent hashing
class DistributedCacheClient {
    std::vector<std::shared_ptr<CacheNode>> nodes_;
    std::unique_ptr<AuditLogger> logger_;
    std::string default_namespace_;

    size_t hash_to_node(const std::string& key) {
        std::hash<std::string> hasher;
        return hasher(key) % nodes_.size();
    }

    // Format audit entry for batch operations
    std::string format_audit_entry(const std::string& op, 
                                    const std::string& wire_key,
                                    const std::string& node_id) {
        // Decode wire key to get original key for audit
        auto [ns, original_key] = KeyEncoder::decode_from_wire(wire_key);

        // Build the audit SQL - escape decoded key since it came from user
        std::string query = "INSERT INTO audit_log "
            "(timestamp, operation, cache_key, node_id, metadata) VALUES ("
            "'2024-01-15T10:30:00Z', '"
            + logger_->get_db()->escape(op) + "', '"
            + logger_->get_db()->escape(original_key) + "', '"
            + logger_->get_db()->escape(node_id) + "', '"
            + "ns=" + logger_->get_db()->escape(ns) + "')";
        return query;
    }

public:
    DistributedCacheClient(const std::string& ns = "default") 
        : logger_(std::make_unique<AuditLogger>()), default_namespace_(ns) {
        nodes_.push_back(std::make_shared<CacheNode>("node-1", "10.0.0.1", 6379));
        nodes_.push_back(std::make_shared<CacheNode>("node-2", "10.0.0.2", 6379));
        nodes_.push_back(std::make_shared<CacheNode>("node-3", "10.0.0.3", 6379));
    }

    bool put(const std::string& key, const std::string& value) {
        std::string wire_key = KeyEncoder::encode_for_wire(default_namespace_, key);
        size_t node_idx = hash_to_node(wire_key);
        auto& node = nodes_[node_idx];

        // Single operation uses safe path
        AuditEvent evt{"2024-01-15T10:30:00Z", "PUT", key, node->id(), ""};
        logger_->log_operation(evt);
        return true;
    }

    // Batch put for performance-critical paths
    bool put_batch(const std::vector<std::pair<std::string, std::string>>& entries) {
        std::vector<std::string> audit_entries;

        for (const auto& [key, value] : entries) {
            std::string wire_key = KeyEncoder::encode_for_wire(default_namespace_, key);
            size_t node_idx = hash_to_node(wire_key);
            auto& node = nodes_[node_idx];

            // Use batch audit format for performance
            audit_entries.push_back(
                format_audit_entry("PUT_BATCH", wire_key, node->id()));
        }

        logger_->log_batch(audit_entries);
        return true;
    }

    std::string get(const std::string& key) {
        std::string wire_key = KeyEncoder::encode_for_wire(default_namespace_, key);
        size_t node_idx = hash_to_node(wire_key);
        auto& node = nodes_[node_idx];

        AuditEvent evt{"2024-01-15T10:30:00Z", "GET", key, node->id(), ""};
        logger_->log_operation(evt);
        return "cached_value"; // simplified
    }
};

// Example usage
int main() {
    DistributedCacheClient client("myapp");

    // Normal operations
    client.put("user:123", "data");
    client.get("session:abc");

    // Batch operation
    std::vector<std::pair<std::string, std::string>> batch = {
        {"key1", "val1"},
        {"key2", "val2"}
    };
    client.put_batch(batch);

    return 0;
}
